'use client'
import { createMachine, useMachine, cn } from '@cascivo/core'
import { forwardRef } from 'react'
import type { InputHTMLAttributes } from 'react'
import styles from './input.module.css'

const machine = createMachine({
  initial: 'idle' as const,
  states: {
    idle: { on: { FOCUS: 'focused' } },
    focused: { on: { BLUR: 'idle' } },
  },
})

export interface InputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'size'> {
  /**
   * Invisible accessible name, for when a visible element outside this component already
   * labels it (a heading in a settings row, a table column header) and `label` would render
   * that text a second time.
   *
   * `label` on this component is **visible** — it is painted next to the control. The catalog
   * splits that way deliberately, but `IconButton.label` and `Sparkline.label` are invisible
   * names, so an adopter arriving with that prior writes `label` here and gets the text twice
   * (2026-08-22 report item 13). Both props are now listed side by side, each saying which it
   * is, which is the only thing that interrupts a confident wrong guess.
   *
   * The raw DOM `aria-label` is still accepted and wins over this.
   */
  ariaLabel?: string
  label?: string
  hint?: string
  error?: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * AI presence: an AI-tinted border and a soft aura, marking a value AI produced or
   * suggested. Visual only — put an AiBadge in the label so the provenance is also text, and
   * clear `ai` once the person edits the value.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  ai?: boolean
}

/**
 * `forwardRef` so `ref` reaches the underlying `<input>` — and so it is TYPED. See
 * `textarea.tsx` for the full rationale (2026-07-28 report C10): the ref already worked at
 * runtime under React 19, but nothing declared it, so passing one was a `ts(2322)` and every
 * consumer had to cast. `forwardRef` rather than a bare `ref?: Ref<T>` prop keeps the
 * `react >= 18` peer floor honest, since ref-as-prop does not work there.
 */
export const Input = forwardRef<HTMLInputElement, InputProps>(function Input(
  {
    label,
    hint,
    error,
    size = 'md',
    ai = false,
    ariaLabel,
    className,
    id,
    onFocus,
    onBlur,
    ...props
  },
  ref,
) {
  const [state, send] = useMachine(machine)
  const inputId =
    id ?? (label ? `cascade-input-${label.toLowerCase().replace(/\s+/g, '-')}` : undefined)

  return (
    <div
      className={cn(styles['wrapper'], className)}
      data-state={error ? 'error' : state.value}
      data-size={size}
      data-ai={ai ? '' : undefined}
    >
      {label && (
        <label className={styles['label']} htmlFor={inputId}>
          {label}
        </label>
      )}
      <input
        ref={ref}
        id={inputId}
        className={styles['input']}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${inputId}-error` : hint ? `${inputId}-hint` : undefined}
        onFocus={(e) => {
          send('FOCUS')
          onFocus?.(e)
        }}
        onBlur={(e) => {
          send('BLUR')
          onBlur?.(e)
        }}
        {...props}
        aria-label={props['aria-label'] ?? ariaLabel}
      />
      {error && (
        <span id={`${inputId}-error`} className={styles['error']} role="alert">
          {error}
        </span>
      )}
      {!error && hint && (
        <span id={`${inputId}-hint`} className={styles['hint']}>
          {hint}
        </span>
      )}
    </div>
  )
})

@layer cascivo.component {
  .wrapper {
    /* A grid/flex item's default minimum is its content size, so a control with an
       intrinsic width (an <input> defaults to ~20ch) refuses to shrink and spills out of
       its track — reported as "Input overflows its grid cell" inside <Grid cols={{md:2}}>. */
    min-inline-size: 0;
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);

    &[data-size='sm'] {
      --_input-height: var(--cascivo-control-height-sm);
      --_input-font: var(--cascivo-text-sm);
      --_input-px: var(--cascivo-space-3);
    }

    &[data-size='md'] {
      --_input-height: var(--cascivo-control-height-md);
      --_input-font: var(--cascivo-text-sm);
      --_input-px: var(--cascivo-space-4);
    }

    &[data-size='lg'] {
      --_input-height: var(--cascivo-control-height-lg);
      --_input-font: var(--cascivo-text-base);
      --_input-px: var(--cascivo-space-4);
    }
  }

  .label {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
    line-height: var(--cascivo-leading-snug);
  }

  .input {
    width: 100%;
    height: var(--_input-height, 2.5rem);
    padding-inline: var(--_input-px, var(--cascivo-space-4));
    font-family: var(--cascivo-font-sans);
    font-size: var(--_input-font, var(--cascivo-text-sm));
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-field);
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);
    outline: none;

    &::placeholder {
      color: var(--cascivo-color-text-muted);
    }

    /* AI presence — the value was produced or suggested by AI. Under :where() so hover,
       focus and the error state (all later or more specific) still win. */
    :where(.wrapper[data-ai]) & {
      border-color: var(--cascivo-color-ai-border);
      background-image: linear-gradient(to top, var(--cascivo-color-ai-subtle), transparent);
    }

    &:hover:not(:disabled):not(:focus) {
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus {
      border-color: var(--cascivo-color-accent);
      box-shadow: var(--cascivo-focus-ring);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
      background-color: var(--cascivo-color-bg-subtle);
    }

    .wrapper[data-state='error'] & {
      border-color: var(--cascivo-color-destructive);

      /* Failed validation had no motion at all, which made a rejected submit easy to miss
         when the error text rendered below the fold. The shake runs once, when the error
         state is applied — CSS restarts an animation as the selector starts matching, so
         no JS is needed to trigger it, and it does not re-run while the error persists.
         Finite and token-timed, so the global reduced-motion collapse disables it. */
      animation: global(cascivo-shake) var(--cascivo-motion-attention) 1;

      &:focus {
        box-shadow: 0 0 0 3px rgb(from var(--cascivo-color-destructive) r g b / 0.3);
      }
    }
  }

  .error {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-destructive);
    line-height: var(--cascivo-leading-snug);
  }

  .hint {
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-snug);
  }

  /* Coarse-pointer touch targets — raise minimum to 44px, desktop density unchanged */
  @media (pointer: coarse) {
    .wrapper[data-size='sm'] .input,
    .wrapper[data-size='md'] .input {
      min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    }
  }
}

@media (forced-colors: active) {
  .input {
    border: 1px solid FieldText;
    color: FieldText;
    background-color: Field;
  }

  .input:focus {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Input',
  description: 'Text input field with optional label, hint, and error state',
  category: 'inputs',
  clientJs: 'enhancement',
  states: ['idle', 'focused', 'error'],
  variants: [],
  sizes: ['sm', 'md', 'lg'],
  props: [
    {
      name: 'label',
      nameVisibility: 'visible',
      description:
        'Text label for the control (standalone use). Omit it when wrapping the Input in a Field — the Field owns the label, and setting both double-labels the control.',
      type: 'string',
      required: false,
    },
    {
      name: 'hint',
      description: 'Supplementary hint text shown with the control.',
      type: 'string',
      required: false,
    },
    {
      name: 'error',
      description: 'Error message shown when the value is invalid.',
      type: 'string',
      required: false,
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md' | 'lg'",
      required: false,
      default: 'md',
    },
    {
      name: 'placeholder',
      description: 'Placeholder text shown when the field is empty.',
      type: 'string',
      required: false,
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'ariaLabel',
      description:
        'Invisible accessible name, for when a visible element outside this component already labels it and `label` would render that text a second time. ⚠ `label` on this component is **visible**; `IconButton.label`/`Sparkline.label` are invisible names, which is the prior that costs adopters a duplicated label. The raw DOM `aria-label` still wins over this.',
      type: 'string',
      required: false,
      nameVisibility: 'invisible',
    },
    {
      name: 'ai',
      type: 'boolean',
      required: false,
      default: 'false',
      description:
        'AI presence: an AI-tinted border and a soft aura, marking a value AI produced or suggested. Visual only — put an AiBadge in the label so the provenance is also text, and clear `ai` once the person edits the value.',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-accent',
    '--cascivo-color-destructive',
    '--cascivo-radius-input',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'textbox',
    wcag: '2.2-AA',
    keyboard: ['Tab', 'Shift+Tab'],
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    { title: 'With label', code: '<Input label="Email" placeholder="you@example.com" />' },
    { title: 'With error', code: '<Input label="Email" error="Invalid email address" />' },
    {
      title: 'AI-suggested value',
      code: '<Input label="Subject" ai defaultValue="Weekly report" />',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['form', 'text', 'input', 'ai'],
  intent: {
    whenToUse: [
      'Collecting a single line of free-form text from the user',
      'Pairing a labelled field with optional hint and validation error messaging',
      'As a field control inside a Form, wired via form.field()',
    ],
    whenNotToUse: [
      'Multi-line text — use Textarea',
      'Choosing from a fixed list of options — use Select, Combobox, or MultiSelect',
      'Editing one read-only value in place — use Editable',
    ],
    antiPatterns: [
      {
        bad: '<Input placeholder="Email" /> with no label',
        good: '<Input label="Email" placeholder="you@example.com" />',
        why: 'Placeholder text disappears on input and is not a substitute for a persistent, programmatically associated label',
      },
    ],
    related: [
      {
        name: 'Form',
        relationship: 'contained-by',
        reason: 'Input is the primary field control wired into a Form store',
      },
      {
        name: 'InputGroup',
        relationship: 'pairs-with',
        reason: 'Wrap Input in InputGroup to add prefix/suffix addons',
      },
      {
        name: 'Textarea',
        relationship: 'alternative',
        reason: 'Use Textarea for multi-line input',
      },
    ],
    a11yRationale:
      'The label is associated to the input via htmlFor/id, error text is linked through aria-describedby and announced with role="alert", and aria-invalid is set when an error is present so assistive tech reports the field as erroneous; visual focus state is driven by CSS, not tracked imperatively.',
    content: {
      tone: 'Concise noun label naming the value',
      notes:
        'Sentence case label; hint and error are full sentences; error states what is wrong and how to fix it',
    },
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Surface, border, accent, destructive, radius, and focus-ring must resolve to the listed --cascivo-* tokens',
      },
      {
        area: 'label / hint / error copy',
        level: 'flexible',
        note: 'Free, within content tone guidance',
      },
      {
        area: 'size',
        level: 'flexible',
        note: 'sm | md | lg, defaulting to md',
      },
    ],
  },
}
